package network.vonix.serverutilities.listener;
import com.mojang.brigadier.CommandDispatcher; import net.minecraft.commands.CommandSourceStack; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerPlayer; import net.minecraft.world.damagesource.DamageSource; import net.minecraft.world.entity.LivingEntity; import network.vonix.serverutilities.VonixServerUtilities; import network.vonix.serverutilities.admin.AdminManager; import network.vonix.serverutilities.command.*; import network.vonix.serverutilities.config.ModConfig; import network.vonix.serverutilities.crates.CratePlaytimeTask; import network.vonix.serverutilities.donation_ranks.*; import network.vonix.serverutilities.features.*; import network.vonix.serverutilities.moderation.ModerationBootstrap; import network.vonix.serverutilities.platform.PlatformEvents; import network.vonix.serverutilities.teleport.TeleportManager; import network.vonix.serverutilities.venary.*;
public final class EventHandler { private EventHandler() {} public static void init() { ModerationBootstrap.init(); PlatformEvents.Holder.get().register(new PlatformEvents.Callbacks(EventHandler::registerCommands,EventHandler::serverStarting,EventHandler::serverStarted,EventHandler::serverStopping,EventHandler::serverStopped,EventHandler::serverTick,EventHandler::playerJoin,EventHandler::playerQuit,EventHandler::livingDeath)); } private static void registerCommands(CommandDispatcher<CommandSourceStack>d){ModCommands.register(d);CrateCommands.register(d);UtilityCommands.register(d);WorldCommands.register(d);LinkCommands.register(d);ModerationBootstrap.registerCommands(d);} private static void serverStarting(MinecraftServer s){ModConfig.INSTANCE.load(s.getServerDirectory().toPath().resolve("config"));VonixServerUtilities.getInstance().getDatabase().init(s);VenaryClient.init(ModConfig.INSTANCE.getVenaryConfig());PlayerSyncTask.register();CratePlaytimeTask.register();FeatureRegistry.getInstance();ServerConfigClient.startPolling();} private static void serverStarted(MinecraftServer s){try{RankGroupSyncer.syncAll();}catch(Throwable t){VonixServerUtilities.LOGGER.warn("[VSU] rank sync failed: {}",t.getMessage());}ModerationBootstrap.serverStarted(s);} private static void serverStopping(MinecraftServer s){ModerationBootstrap.serverStopping(s);} private static void serverStopped(MinecraftServer s){TeleportManager.getInstance().clear();AdminManager.getInstance().clear();PlayerSyncTask.clear();CratePlaytimeTask.clear();LinkCommands.clearCooldowns();VonixServerUtilities.getInstance().shutdown();VonixServerUtilities.getInstance().getDatabase().close();} private static void serverTick(MinecraftServer s){PlayerSyncTask.onServerTick(s);CratePlaytimeTask.onServerTick(s);ServerConfigClient.onTick(s);} private static void playerJoin(ServerPlayer p){UtilityCommands.onPlayerJoin(p);PlayerSyncTask.onPlayerJoin(p);RankSyncTask.onJoin(p);} private static void playerQuit(ServerPlayer p){UtilityCommands.onPlayerLeave(p.getUUID());TeleportManager.getInstance().clearPlayer(p.getUUID());PlayerSyncTask.onPlayerLeave(p.getUUID());LinkCommands.onPlayerLeave(p.getUUID());} private static void livingDeath(LivingEntity e,DamageSource s){if(e instanceof ServerPlayer p)TeleportManager.getInstance().saveDeathLocation(p);} }
